/* Tokens are per-tab and memory-only. Never cache Drive responses or credentials. */
const BASE=new URL('./',self.location.href).pathname,MEDIA_PATH=BASE+'drive-media/';
const CACHE_PREFIX='iamtt-shell-'+encodeURIComponent(BASE)+'-',CACHE=CACHE_PREFIX+'v3';
const SHELL=['','index.html','styles.css','app.js','media.mjs','mkv-audio.mjs','compat-audio.mjs','vendor/eac3/decode-eac3.mjs','vendor/eac3/src/eac3.wasm.js','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png'].map(file=>BASE+file);
const sessions=new Map();const waits=new Map();
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(Promise.all([caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(CACHE_PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))),self.clients.claim()])));
self.addEventListener('message',e=>{const client=e.source;if(!client?.id||new URL(client.url).origin!==self.location.origin)return;const d=e.data||{};if(d.type==='AUTH'&&typeof d.token==='string'&&Array.isArray(d.files)){sessions.set(client.id,{token:d.token,expiresAt:Number(d.expiresAt),files:new Map(d.files.map(f=>[f.id,f]))});const done=waits.get(client.id);if(done){waits.delete(client.id);done(sessions.get(client.id))}e.ports[0]?.postMessage({ok:true})}if(d.type==='CLEAR_AUTH'){sessions.delete(client.id);e.ports[0]?.postMessage({ok:true})}});
async function authFor(clientId){let s=sessions.get(clientId);if(s&&s.expiresAt>Date.now()+5000)return s;const client=await self.clients.get(clientId);if(!client)return null;const result=await new Promise(resolve=>{const prior=waits.get(clientId);waits.set(clientId,value=>{prior?.(value);resolve(value)});client.postMessage({type:'TOKEN_NEEDED'});setTimeout(()=>{const done=waits.get(clientId);if(done){waits.delete(clientId);done(null)}},2500)});return result?.expiresAt>Date.now()+5000?result:null}
async function stream(e,url){const id=decodeURIComponent(url.pathname.slice(MEDIA_PATH.length));if(!/^[a-zA-Z0-9_-]+$/.test(id))return new Response('Invalid file',{status:400});const s=await authFor(e.clientId);if(!s?.token){const client=await self.clients.get(e.clientId);client?.postMessage({type:'STREAM_ERROR',status:401});return new Response('Reconnect Google Drive',{status:401})}const file=s.files.get(id);if(!file)return new Response('Select this video in your library first',{status:403});const headers=new Headers({Authorization:'Bearer '+s.token});const range=e.request.headers.get('Range');if(range)headers.set('Range',range);
 try{const upstream=await fetch('https://www.googleapis.com/drive/v3/files/'+encodeURIComponent(id)+'?alt=media&supportsAllDrives=true',{headers,method:e.request.method,credentials:'omit',cache:'no-store',signal:e.request.signal});if(!upstream.ok){const client=await self.clients.get(e.clientId);client?.postMessage({type:'STREAM_ERROR',status:upstream.status});return new Response('Drive playback failed',{status:upstream.status})}
 const h=new Headers({'Cache-Control':'no-store','Content-Type':upstream.headers.get('Content-Type')||file.mimeType||'video/mp4','Accept-Ranges':'bytes'});for(const k of ['Content-Length','Content-Range']){const v=upstream.headers.get(k);if(v)h.set(k,v)}
 // CORS may hide Content-Range. It can be reconstructed from a single byte range and known Drive size.
 if(upstream.status===206&&!h.has('Content-Range')&&range&&Number(file.size)>0){const m=/^bytes=(\d*)-(\d*)$/.exec(range);if(m){const size=Number(file.size);const start=m[1]?Number(m[1]):Math.max(0,size-Number(m[2]));const end=m[1]&&m[2]?Math.min(Number(m[2]),size-1):size-1;h.set('Content-Range',`bytes ${start}-${end}/${size}`);if(!h.has('Content-Length'))h.set('Content-Length',String(end-start+1))}}
 return new Response(upstream.body,{status:upstream.status,headers:h});}catch{return new Response('Drive is unreachable',{status:502})}}
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(url.origin!==self.location.origin)return;if(url.pathname.startsWith(MEDIA_PATH)){e.respondWith(stream(e,url));return}if(e.request.method!=='GET'||!SHELL.includes(url.pathname))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&r.headers.get('Content-Type')?.includes(url.pathname.endsWith('.js')||url.pathname.endsWith('.mjs')?'javascript':url.pathname.endsWith('.css')?'text/css':url.pathname===BASE||url.pathname.endsWith('.html')?'text/html':url.pathname.endsWith('.png')?'image/png':url.pathname.endsWith('.svg')?'image/svg+xml':'json')){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)))}return r}).catch(()=>caches.match(e.request).then(r=>r||Response.error())))});

